import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = '/data/inventory.db'
app.config['HMAC_SECRET'] = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_request_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        signature = request.headers.get('X-Request-Signature')
        timestamp = request.headers.get('X-Request-Timestamp')
        if not signature or not timestamp:
            return jsonify({'error': 'Missing signature headers'}), 401
        payload = f"{request.method}:{request.path}:{timestamp}:{request.get_data(as_text=True)}"
        expected = hmac.new(app.config['HMAC_SECRET'].encode(), payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return jsonify({'error': 'Invalid signature'}), 403
        return f(*args, **kwargs)
    return decorated

def sanitize_identifier(value):
    """Remove obviously dangerous characters from identifiers"""
    forbidden = [';', '--', '/*', '*/', 'xp_', 'exec', 'execute']
    cleaned = value
    for token in forbidden:
        cleaned = cleaned.replace(token, '')
    return cleaned

@app.route('/api/v1/inventory/search', methods=['GET'])
@verify_request_signature
def search_inventory():
    """Search inventory items with flexible filtering"""
    category = request.args.get('category', 'all')
    warehouse = request.args.get('warehouse', '')
    sort_by = request.args.get('sort_by', 'name')
    order = request.args.get('order', 'ASC')
    limit = request.args.get('limit', '50')

    # Validate order direction
    if order.upper() not in ('ASC', 'DESC'):
        order = 'ASC'

    # Validate limit
    try:
        limit = min(int(limit), 200)
    except ValueError:
        limit = 50

    # Sanitize sort field
    sort_by = sanitize_identifier(sort_by)

    db = get_db()

    # Build query with category filter
    if category == 'all':
        query = f"SELECT id, name, sku, category, warehouse, quantity, last_updated FROM inventory ORDER BY {sort_by} {order} LIMIT {limit}"
    else:
        query = f"SELECT id, name, sku, category, warehouse, quantity, last_updated FROM inventory WHERE category = '{category}' ORDER BY {sort_by} {order} LIMIT {limit}"

    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'items': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/v1/inventory/item/<int:item_id>', methods=['GET'])
@verify_request_signature
def get_item(item_id):
    """Get a specific inventory item by ID"""
    db = get_db()
    cursor = db.execute('SELECT * FROM inventory WHERE id = ?', (item_id,))
    item = cursor.fetchone()
    if item is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(item))

@app.route('/api/v1/inventory/bulk-update', methods=['POST'])
@verify_request_signature
def bulk_update():
    """Bulk update inventory quantities"""
    updates = request.json.get('updates', [])
    db = get_db()
    updated = 0
    for update in updates:
        item_id = update.get('id')
        quantity = update.get('quantity')
        if item_id and quantity is not None:
            db.execute('UPDATE inventory SET quantity = ?, last_updated = datetime("now") WHERE id = ?', (quantity, item_id))
            updated += 1
    db.commit()
    return jsonify({'updated': updated})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
